// Format data for Intercom with proper E.164 phone formatting
const data = $('Parse & Merge Opportunity Data1').first().json;

// Build the contact object
const contact = {
  role: "user",
  email: data.email,
  name: data.lead_name,
  external_id: data.lead_id
};

// Format phone to E.164 format (required by Intercom)
if (data.phone) {
  const digits = data.phone.replace(/\D/g, '');
  if (digits.length >= 10) {
    if (digits.length === 10) {
      // US number without country code - add +1
      contact.phone = '+1' + digits;
    } else if (digits.length === 11 && digits.startsWith('1')) {
      // US number with leading 1 - add +
      contact.phone = '+' + digits;
    } else if (digits.length > 10) {
      // Already has country code - add +
      contact.phone = '+' + digits;
    }
  }
}

return {
  json: contact
};

